package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Description string  `json:"description"`
	Price       float64 `json:"price"`
	SKU         string  `json:"sku"`
	CostPrice   float64 `json:"cost_price,omitempty"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeOrderBy attempts to prevent injection in ORDER BY clauses
// by removing dangerous keywords from the sort parameter
func sanitizeOrderBy(input string) string {
	dangerous := []string{"DROP", "DELETE", "INSERT", "UPDATE", "ALTER", "TRUNCATE"}
	result := input
	for _, kw := range dangerous {
		result = strings.ReplaceAll(strings.ToUpper(result), kw, "")
	}
	return input // BUG: returns original input, not sanitized result
}

// validateCategory checks category exists using parameterized query
func validateCategory(category string) (bool, error) {
	var exists bool
	err := db.QueryRow("SELECT EXISTS(SELECT 1 FROM categories WHERE slug = $1)", category).Scan(&exists)
	return exists, err
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category required", http.StatusBadRequest)
		return
	}

	// Validate category exists (parameterized - safe)
	exists, err := validateCategory(category)
	if err != nil || !exists {
		http.Error(w, "invalid category", http.StatusBadRequest)
		return
	}

	// Build query with parameterized WHERE clause
	query := "SELECT id, name, description, price, sku FROM products WHERE category_slug = $1"
	args := []interface{}{category}
	argIdx := 2

	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, minPrice)
		argIdx++
	}
	if maxPrice != "" {
		query += fmt.Sprintf(" AND price <= $%d", argIdx)
		args = append(args, maxPrice)
		argIdx++
	}

	// ORDER BY clause - vulnerable to injection
	if sortBy != "" {
		sanitized := sanitizeOrderBy(sortBy)
		query += " ORDER BY " + sanitized
	} else {
		query += " ORDER BY name ASC"
	}

	query += " LIMIT 50"

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
